47	
48	    private static final RowMapper<AllocationRow> ALLOCATION_MAPPER = (rs, n) -> new AllocationRow(
49	            rs.getLong("id"), rs.getString("allocation_key"), rs.getLong("window_id"),
50	            rs.getString("user_id"), rs.getBigDecimal("amount"), rs.getString("requester"),
51	            rs.getString("status"), rs.getLong("created_nanos"), rs.getLong("updated_nanos"));
52	
53	    private static final RowMapper<CurtailmentRow> CURTAILMENT_MAPPER = (rs, n) -> new CurtailmentRow(
54	            rs.getLong("id"), rs.getLong("window_id"), rs.getBigDecimal("volume"), rs.getString("status"),
55	            rs.getLong("created_nanos"),
56	            rs.getObject("cancelled_nanos") == null ? null : rs.getLong("cancelled_nanos"));
57	
58	    private static final RowMapper<CommandRow> COMMAND_MAPPER = (rs, n) -> new CommandRow(
59	            rs.getString("command_key"), rs.getString("operation"), rs.getString("params"),
60	            rs.getString("response"), rs.getLong("created_nanos"));
