3	import org.springframework.http.HttpStatus;
4	
5	/**
6	 * 业务异常：携带 HTTP 状态与可区分的错误码。
7	 * 400 参数非法、404 不存在、409 操作人/状态/幂等冲突、422 配额不足。
8	 */
9	public class ApiException extends RuntimeException {
10	
11	    private final HttpStatus status;
12	    private final String code;
13	
14	    public ApiException(HttpStatus status, String code, String message) {
15	        super(message);
16	        this.status = status;
17	        this.code = code;
18	    }
19	
20	    public HttpStatus status() {
21	        return status;
22	    }
23	
24	    public String code() {
25	        return code;
26	    }
27	
28	    public static ApiException badRequest(String code, String message) {
29	        return new ApiException(HttpStatus.BAD_REQUEST, code, message);
30	    }
31	
32	    public static ApiException notFound(String code, String message) {
33	        return new ApiException(HttpStatus.NOT_FOUND, code, message);
34	    }
35	
36	    public static ApiException conflict(String code, String message) {
37	        return new ApiException(HttpStatus.CONFLICT, code, message);
38	    }
